set statement_timeout='600s'; set work_mem='64MB';
\copy (select platform, count(*) n, count(distinct product_id) products, round(avg((author is not null and author<>'')::int)*100,1) author_pct, round(avg((written_at is not null)::int)*100,1) written_pct, round(avg((written_at is not null and written_at::time<>'00:00' and extract(second from written_at)=0 and written_at::time<>'15:00')::int)*100,1) has_time_pct, round(avg((option is not null and option<>'')::int)*100,1) option_pct, round(avg((cardinality(images)>0)::int)*100,1) image_pct, round(avg((helpful_count is not null)::int)*100,1) helpful_pct, round(avg((raw_payload is not null)::int)*100,1) raw_pct, round(avg((rating is not null)::int)*100,1) rating_pct, round(avg((rating=5)::int)*100,1) r5_pct, round(avg((rating<=2)::int)*100,1) r12_pct, percentile_cont(0.5) within group (order by char_length(content)) len_p50, round(avg((char_length(content)<10)::int)*100,1) short_pct, min(written_at)::date first_w, max(written_at)::date last_w from reviews group by platform order by 2 desc) to stdout with csv header
